@@ -0,0 +1,113 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Markdown Editor</title>
+    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@4.6.0/dist/css/bootstrap.min.css">
+    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.4.0/font/bootstrap-icons.css">
+    <style>
+        body {
+            font-family: Arial, sans-serif;
+        }
+        .container {
+            max-width: 800px;
+            margin: 40px auto;
+            padding: 20px;
+            background-color: #f9f9f9;
+            border: 1px solid #ddd;
+            box-shadow: 0 0 10px rgba(0,0,0,0.1);
+        }
+        .editor {
+            width: 45%;
+            height: 600px;
+            padding: 20px;
+            border: 1px solid #ccc;
+            border-radius: 5px;
+            box-shadow: 0 0 10px rgba(0,0,0,0.1);
+            float: left;
+        }
+        .preview {
+            width: 45%;
+            height: 600px;
+            padding: 20px;
+            border: 1px solid #ccc;
+            border-radius: 5px;
+            box-shadow: 0 0 10px rgba(0,0,0,0.1);
+            float: right;
+        }
+        .counters {
+            margin-top: 20px;
+            font-size: 14px;
+        }
+        .theme-toggle {
+            margin-top: 20px;
+        }
+        .copy-button {
+            margin-top: 20px;
+        }
+    </style>
+</head>
+<body>
+    <div class="container">
+        <h1>Markdown Editor</h1>
+        <div class="editor">
+            <textarea id="markdown-input" placeholder="Type your markdown here..."></textarea>
+        </div>
+        <div class="preview">
+            <div id="markdown-preview"></div>
+        </div>
+        <div class="counters">
+            <span id="char-count">Characters: 0</span> | <span id="word-count">Words: 0</span>
+        </div>
+        <div class="theme-toggle">
+            <button id="theme-toggle-button" class="btn btn-sm btn-secondary">Toggle Theme</button>
+        </div>
+        <div class="copy-button">
+            <button id="copy-button" class="btn btn-sm btn-primary">Copy to Clipboard</button>
+        </div>
+    </div>
+
+    <script src="https://cdn.jsdelivr.net/npm/bootstrap@4.6.0/dist/js/bootstrap.bundle.min.js"></script>
+    <script>
+        const markdownInput = document.getElementById('markdown-input');
+        const markdownPreview = document.getElementById('markdown-preview');
+        const charCount = document.getElementById('char-count');
+        const wordCount = document.getElementById('word-count');
+        const themeToggleButton = document.getElementById('theme-toggle-button');
+        const copyButton = document.getElementById('copy-button');
+
+        // Live markdown preview
+        markdownInput.addEventListener('input', () => {
+            const markdown = markdownInput.value;
+            const html = marked(markdown);
+            markdownPreview.innerHTML = html;
+        });
+
+        // Live character and word counters
+        markdownInput.addEventListener('input', () => {
+            const text = markdownInput.value;
+            const charCountValue = text.length;
+            const wordCountValue = text.trim().split(/s+/).length;
+            charCount.textContent = `Characters: ${charCountValue}`;
+            wordCount.textContent = `Words: ${wordCountValue}`;
+        });
+
+        // Theme toggle
+        themeToggleButton.addEventListener('click', () => {
+            document.body.classList.toggle('dark-theme');
+        });
+
+        // Copy to clipboard
+        copyButton.addEventListener('click', () => {
+            const text = markdownInput.value;
+            navigator.clipboard.writeText(text).then(() => {
+                alert('Text copied to clipboard!');
+            }, () => {
+                alert('Failed to copy text to clipboard.');
+            });
+        });
+    </script>
+    <script src="https://cdn.jsdelivr.net/npm/marked@4.0.1/dist/marked.min.js"></script>
+</body>
+</html>
